query:
PREFIX ix: <http://trustgraph.ai/ontology/interaction#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?actorId ?purpose ?outcome ?startDate ?endDate (COUNT(?session) AS ?sessionCount)
WHERE {
  ?journey a ix:Journey ;
           ix:journeyActor ?actor ;
           ix:journeyPurpose ?purpose ;
           ix:journeyOutcome ?outcome ;
           ix:journeyStartDate ?startDate ;
           ix:hasSession ?session .
  ?actor ix:actorId ?actorId .
  OPTIONAL { ?journey ix:journeyEndDate ?endDate }
}
GROUP BY ?actorId ?purpose ?outcome ?startDate ?endDate
ORDER BY ?startDate

PREFIX ix: <http://trustgraph.ai/ontology/interaction#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?seqIndex ?eventType ?timestamp ?dwellTime
WHERE {
  ?journey a ix:Journey ;
           ix:journeyPurpose ?purpose ;
           ix:hasSession ?session .
  ?event ix:inSession ?session ;
         ix:sequenceIndex ?seqIndex ;
         ix:timestamp ?timestamp ;
         a ?eventType .
  ?eventType rdfs:subClassOf ix:InteractionEvent .
  OPTIONAL { ?event ix:dwellTimeSeconds ?dwellTime }
  FILTER(?purpose = "1440p gaming PC build")
}
ORDER BY ?timestamp ?seqIndex

PREFIX ix: <http://trustgraph.ai/ontology/interaction#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?categoryLabel ?statedReason ?resolved ?resolvedBy ?journeyPurpose
WHERE {
  ?event a ix:Objection ;
         ix:hasObjectionType ?category ;
         ix:objectionResolved ?resolved ;
         ix:inSession ?session .
  ?category rdfs:label ?categoryLabel .
  ?session ix:belongsToJourney ?journey .
  ?journey ix:journeyPurpose ?journeyPurpose .
  OPTIONAL { ?event ix:statedReason ?statedReason }
  OPTIONAL { ?event ix:resolvedBy ?resolvedBy }
}
ORDER BY ?categoryLabel

PREFIX ix: <http://trustgraph.ai/ontology/interaction#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX rt: <http://trustgraph.ai/ontology/retail#>

SELECT ?journeyPurpose ?selectedName ?rejectedName ?reasoning
WHERE {
  ?event a ix:DecisionPoint ;
         ix:selectedOption ?selected ;
         ix:rejectedOption ?rejected ;
         ix:inSession ?session .
  ?selected rdfs:label ?selectedName .
  ?rejected rdfs:label ?rejectedName .
  ?session ix:belongsToJourney ?journey .
  ?journey ix:journeyPurpose ?journeyPurpose .
  OPTIONAL { ?event ix:decisionReasoning ?reasoning }
}
ORDER BY ?journeyPurpose

PREFIX ix: <http://trustgraph.ai/ontology/interaction#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?journeyPurpose ?statedBudget ?constraintType ?signalStrength
WHERE {
  ?event a ix:BudgetSignal ;
         ix:inSession ?session .
  ?session ix:belongsToJourney ?journey .
  ?journey ix:journeyPurpose ?journeyPurpose .
  OPTIONAL { ?event ix:statedBudget ?statedBudget }
  OPTIONAL { ?event ix:budgetConstraintType ?constraintType }
  OPTIONAL { ?event ix:signalStrength ?signalStrength }
}
ORDER BY ?journeyPurpose

PREFIX ix: <http://trustgraph.ai/ontology/interaction#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?journeyPurpose ?productName ?accepted ?reason
WHERE {
  ?event a ix:RecommendationReceived ;
         ix:recommendedProduct ?product ;
         ix:recommendationAccepted ?accepted ;
         ix:inSession ?session .
  ?product rdfs:label ?productName .
  ?session ix:belongsToJourney ?journey .
  ?journey ix:journeyPurpose ?journeyPurpose .
  OPTIONAL { ?event ix:recommendationReason ?reason }
}
ORDER BY ?journeyPurpose

PREFIX ix: <http://trustgraph.ai/ontology/interaction#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?journeyPurpose ?dimension ?strength
WHERE {
  ?event a ix:PrioritySignal ;
         ix:priorityDimension ?dimension ;
         ix:inSession ?session .
  ?session ix:belongsToJourney ?journey .
  ?journey ix:journeyPurpose ?journeyPurpose .
  OPTIONAL { ?event ix:signalStrength ?strength }
}
ORDER BY ?journeyPurpose ?dimension

PREFIX ix: <http://trustgraph.ai/ontology/interaction#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?categoryLabel (COUNT(?event) AS ?total)
       (SUM(IF(?resolved, 1, 0)) AS ?resolvedCount)
       (SUM(IF(!?resolved, 1, 0)) AS ?unresolvedCount)
WHERE {
  ?event a ix:Objection ;
         ix:hasObjectionType ?category ;
         ix:objectionResolved ?resolved .
  ?category rdfs:label ?categoryLabel .
}
GROUP BY ?categoryLabel
ORDER BY ?categoryLabel

PREFIX ix: <http://trustgraph.ai/ontology/interaction#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?journeyPurpose ?totalSpend ?productName
WHERE {
  ?event a ix:CheckoutCompleted ;
         ix:totalSpend ?totalSpend ;
         ix:purchasedProduct ?product ;
         ix:inSession ?session .
  ?product rdfs:label ?productName .
  ?session ix:belongsToJourney ?journey .
  ?journey ix:journeyPurpose ?journeyPurpose .
}
ORDER BY ?journeyPurpose ?productName

PREFIX ix: <http://trustgraph.ai/ontology/interaction#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?journeyPurpose ?triggerType ?triggerDescription
WHERE {
  ?event a ix:TriggerEvent ;
         ix:triggerType ?triggerType ;
         ix:inSession ?session .
  ?session ix:belongsToJourney ?journey .
  ?journey ix:journeyPurpose ?journeyPurpose .
  OPTIONAL { ?event ix:triggerDescription ?triggerDescription }
}
ORDER BY ?journeyPurpose

PREFIX ix: <http://trustgraph.ai/ontology/interaction#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?event ?interactionType ?signalType
WHERE {
  ?event a ?interactionType ;
         a ?signalType .
  ?interactionType rdfs:subClassOf ix:InteractionEvent .
  ?signalType rdfs:subClassOf ix:SignalEvent .
}
ORDER BY ?event
